const server = http.createServer((req, res) => {
  req.on("data", () => {});
  req.on("end", () => {
    res.writeHead(200, { "content-type": "text/event-stream" });
    res.write("event: ping\ndata: {}\n\n"); // then hang: never end
  });
});
server.on("connection", (s) => { sockets.add(s); s.on("close", () => sockets.delete(s)); });
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const url = `http://127.0.0.1:${server.address().port}/`;

const dispatcher = new Agent({ keepAliveTimeout: 1000 });
const ac = new AbortController();
const res = await fetch(url, { method: "POST", body: "{}", signal: ac.signal, dispatcher });
const reader = res.body.getReader();
await reader.read();
const t0 = Date.now();
ac.abort();

let closedAt = null;
while (Date.now() - t0 < 5000) {
  if (sockets.size === 0) { closedAt = Date.now() - t0; break; }
  await new Promise((r) => setTimeout(r, 25));
}
console.log(closedAt === null ? `STILL OPEN after 5000 ms (server sockets=${sockets.size})` : `all sockets closed after ${closedAt} ms`);
